!===========================================================================
MODULE sgr_lut
!! This is intended for CLEAR SKY Snow only!!

 USE generic_lut,only : LT_TYPE,lut_guts,lut_init

  implicit none
  PRIVATE
  integer,parameter:: nsg     =  6
  integer,parameter:: nat     =  4
  integer,parameter:: nel     =  5
  integer,parameter:: no3     =  4
  integer,parameter:: npw     =  7
  integer,parameter:: nu0     =  13
  
  integer,parameter:: nrec1 =  nsg *nat *nel *no3 *npw *nu0
  
  TYPE ( LT_TYPE ),save:: lt1
  
 TYPE SGR_TYPE 
  sequence
  !Inputs
  real toa_alb	 ! toa-albedo 
  real aot		! Aerosol Optical Depth 
  real elev		! Sfc Elevation (m) (0 -8000)
  real o3		! Ozone DU ( 200 -500)
  real pw		! Precipitable water (cm) (0-7)
  real u0		! CosSol (0-1)
  !Output
  real snow_grain
 END TYPE SGR_TYPE
 
 logical,save:: inital
  data inital/.true./

PUBLIC sgr200610_lut
PUBLIC SGR_TYPE
TYPE ( SGR_TYPE ) ,PUBLIC:: sgt

 CONTAINS
!=======================================================================
subroutine sgr200610_lut
	integer i
	real toa0
if ( inital ) then 
 inital = .false. 
 
 lt1%nv=6
 lt1%nrec= nrec1
 lt1%scale = 10000.
 lt1%mxn = 13
 call lut_init(lt1)
 
 lt1%nva =(/nsg,nat, nel ,no3 ,npw ,nu0/) !! Table 1 order (fast to slow)

 call sgr200610_load_mem !lut_init's MUST BE CALLED BEFORE OPEN
! print*,'SGR Tables loaded'

 lt1%anodes(1:nsg ,1) =(/ 50., 100., 200., 500., 1000., 2000. /) !!! Snow Grain Size
 lt1%anodes(1:nat, 2) =(/ -7.000, -2.000, -1.000,  0.000 /) !! lnAOT
 lt1%anodes(1:nel ,3) =(/-200.0 ,0.0, 500.0, 1250.0, 4200.0/) !SfcElevation(m)
 lt1%anodes(1:no3 ,4) =(/150.0, 250.0, 350.0, 500.0/)!Ozone(du)
 lt1%anodes(1:npw ,5) =(/-4.0,-3.0,-2.0,-1.0,0.0,1.0,2.0/) !ln(Pw cm)
 lt1%anodes(1:nu0 ,6) =(/0.05, 0.09, 0.15, 0.21, 0.27, 0.33, 0.39, 0.45, 0.52, 0.60, 0.68, 0.76, 0.86 /) !Cos Sol

endif ! inital

toa0 = 1.0

 lt1%val(2) = log(sgt%aot)
 lt1%val(3) = sgt%elev	
 lt1%val(4) = sgt%o3
 lt1%val(5) = log(sgt%pw)	
 lt1%val(6) = sgt%u0

do i=1,nsg !! ASSUME INCREASING SNOW GRAIN gives Decreasing TOA ALBEDO...
 lt1%val(1) =  lt1%anodes(i ,1)	

 call lut_guts(lt1)
 
!  print'(f8.0,3f10.4)' ,lt1%val(1),  lt1%result,sgt%toa_alb,toa0
 if (  i == 1 .and. lt1%result <= sgt%toa_alb  ) then  
   sgt%snow_grain = lt1%anodes(i ,1)
!   print*,i,'TOO BRIGHT , small grain'	
   exit
 elseif ( lt1%result <= sgt%toa_alb  .and.  sgt%toa_alb < toa0 ) then 
!   print'(A2,2f8.0,2f8.0,3f10.3)',&
!   'I',i ,lt1%anodes(i-1 ,1),lt1%anodes(i ,1), lt1%anodes(i ,1),toa0,sgt%toa_alb,lt1%result
   
   sgt%snow_grain = exp( log(lt1%anodes(i-1 ,1)) + &
               (log(lt1%anodes(i ,1) / lt1%anodes(i-1 ,1)) * &
                ((sgt%toa_alb-toa0) / (lt1%result-toa0)) ) )
				
   exit
        
 endif
  
   sgt%snow_grain = 2000.
  toa0=lt1%result
enddo
 return
end subroutine  sgr200610_lut
